List<String> bodyStructureMids(String major) =>
    List.unmodifiable(_bodyStructure[major]?.keys ?? const <String>[]);

/// 指定（大項目, 中項目）の小項目（キーワード）
List<String> bodyStructureTopicsOf(String major, String mid) =>
    List.unmodifiable(_bodyStructure[major]?[mid] ?? const <String>[]);

